import"./object_fieldset.js";import{$}from"chrome://resources/js/util.js";import{Page}from"./page.js";const PROPERTY_NAMES={address:"Address",name:"Name",systemName:"System Name",floss:"Floss",initialized:"Initialized",present:"Present",powered:"Powered",discoverable:"Discoverable",discovering:"Discovering"};export class AdapterPage extends Page{constructor(){super("adapter","Adapter","adapter");this.adapterFieldSet=document.createElement("object-field-set");this.adapterFieldSet.toggleAttribute("show-all",true);this.adapterFieldSet.dataset.nameMap=JSON.stringify(PROPERTY_NAMES);this.pageDiv.appendChild(this.adapterFieldSet);this.refreshBtn_=$("adapter-refresh-btn");this.refreshBtn_.addEventListener("click",(event=>{this.refreshBtn_.disabled=true;this.pageDiv.dispatchEvent(new CustomEvent("refreshpressed"))}));const restartBluetoothBtn=$("restart-bluetooth-btn");restartBluetoothBtn.addEventListener("click",(()=>{restartBluetoothBtn.disabled=true;this.pageDiv.dispatchEvent(new CustomEvent("restart-bluetooth-click"))}))}setAdapterInfo(info){if(info.hasOwnProperty("systemName")&&!info.systemName){delete info.systemName}this.adapterFieldSet.dataset.value=JSON.stringify(info);this.refreshBtn_.disabled=false}}